import { randomUUID } from 'node:crypto';
import type { ObjectStorage } from '../storage/object-storage';
import type { AttachmentRepository } from './attachment-repository';

const MAX_BYTES = 25 * 1024 * 1024;
const EXTENSION_BY_TYPE: Record<string, string> = {
  'image/png': 'png',
  'image/jpeg': 'jpg',
  'application/pdf': 'pdf',
};

export class HttpError extends Error {
  constructor(readonly status: number, message: string) {
    super(message);
  }
}

export interface UploadInput {
  ticketId: string;
  fileName: string;
  contentType: string;
  body: Buffer;
}

export class AttachmentHandler {
  constructor(
    private readonly storage: ObjectStorage,
    private readonly attachments: AttachmentRepository,
  ) {}

  async upload(input: UploadInput): Promise<{ id: string }> {
    if (input.body.byteLength > MAX_BYTES) {
      throw new HttpError(413, 'attachment is too large');
    }
    const extension = EXTENSION_BY_TYPE[input.contentType];
    if (!extension) {
      throw new HttpError(415, 'unsupported attachment type');
    }

    const id = randomUUID();
    const key = 'tickets/' + input.ticketId + '/' + id + '.' + extension;
    await this.storage.put(key, input.body, input.contentType);
    await this.attachments.insert({
      id,
      ticketId: input.ticketId,
      key,
      displayName: input.fileName.slice(0, 120),
      status: 'available',
    });
    return { id };
  }
}

