import type { Router } from '../http/router';
import { AttachmentHandler } from './attachment-handler';
import { TicketHandler } from './ticket-handler';

export function registerTicketRoutes(router: Router, deps: TicketDeps): void {
  const tickets = new TicketHandler(deps.tickets);
  const attachments = new AttachmentHandler(deps.storage, deps.attachments);

  router.post('/tickets', (req) => tickets.create(req.body));
  router.get('/tickets/:id', (req) => tickets.get(req.params.id));
  router.post('/tickets/:id/attachments', (req) =>
    attachments.upload({
      ticketId: req.params.id,
      fileName: req.file.name,
      contentType: req.file.type,
      body: req.file.buffer,
    }),
  );
}
